package main

import (
	"fmt"
	"os"
)

func main() {
	var a, b, c, l int64
	fmt.Fscan(os.Stdin, &a, &b, &c, &l)

	// Total number of ways to distribute at most l increments among 3 sticks
	// Number of non-negative integer solutions to x+y+z <= l is C(l+3, 3)
	totalWays := (l + 1) * (l + 2) * (l + 3) / 6

	bad := int64(0)

	// We count bad cases for each stick being the "longest" (violating triangle inequality)
	// Case 1: a is the largest side. We need a + da >= b + db + c + dc
	// Let x = da, y = db, z = dc. x, y, z >= 0, x + y + z <= l.
	// a + x >= b + y + c + z  => x - y - z >= b + c - a
	// Let diff = b + c - a.
	// If diff <= 0, inequality holds for all x,y,z (since x-y-z >= -l >= diff). Bad count = totalWays.
	// If diff > 0, we need x >= y + z + diff.
	// Substitute x' = x - (y + z + diff). x' >= 0.
	// x' + y + z + diff + y + z <= l => x' + 2y + 2z <= l - diff.
	// Let L = l - diff. If L < 0, bad = 0.
	// Count non-negative integer solutions to x' + 2y + 2z <= L.
	// Iterate y from 0 to L/2.
	// For each y, z from 0 to (L - 2y)/2.
	// For each (y,z), x' from 0 to L - 2y - 2z.
	// Count = sum_{y=0}^{floor(L/2)} sum_{z=0}^{floor((L-2y)/2)} (L - 2y - 2z + 1)
	// Let k = y + z. 2k <= L. For fixed k, number of (y,z) pairs is k+1.
	// Sum = sum_{k=0}^{floor(L/2)} (k+1) * (L - 2k + 1)
	// This can be computed in O(1) using formulas or O(L) loop. L <= 3e5, O(L) is fine.

	diff1 := b + c - a
	if diff1 <= 0 {
		bad += totalWays
	} else {
		L := l - diff1
		if L >= 0 {
			// sum_{k=0}^{floor(L/2)} (k+1)*(L - 2k + 1)
			m := L / 2
			// S1 = sum (k+1) = (m+1)(m+2)/2
			// S2 = sum (k+1)*k = sum(k^2+k) = m(m+1)(2m+1)/6 + m(m+1)/2 = m(m+1)(2m+1+3)/6 = m(m+1)(m+2)/3
			// S3 = sum (k+1)*2k = 2*S2
			// Sum = (L+1)*S1 - 2*S2
			s1 := (m + 1) * (m + 2) / 2
			s2 := m * (m + 1) * (m + 2) / 3
			bad += (L + 1) * s1 - 2 * s2
		}
	}

	// Case 2: b is the largest side.
	diff2 := a + c - b
	if diff2 <= 0 {
		bad += totalWays
	} else {
		L := l - diff2
		if L >= 0 {
			m := L / 2
			s1 := (m + 1) * (m + 2) / 2
			s2 := m * (m + 1) * (m + 2) / 3
			bad += (L + 1) * s1 - 2 * s2
		}
	}

	// Case 3: c is the largest side.
	diff3 := a + b - c
	if diff3 <= 0 {
		bad += totalWays
	} else {
		L := l - diff3
		if L >= 0 {
			m := L / 2
			s1 := (m + 1) * (m + 2) / 2
			s2 := m * (m + 1) * (m + 2) / 3
			bad += (L + 1) * s1 - 2 * s2
		}
	}

	ans := totalWays - bad
	fmt.Println(ans)
}
